package org.duofold.live;import android.os.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class LiveAngles{public static AtomicInteger guards=new AtomicInteger();public static volatile CountDownLatch validating=new CountDownLatch(1),release=new CountDownLatch(1);public static boolean rejectBefore,rejectAfter;
 public static IBinder captureBinder(){return (code,p,r,flags)->{if(code!=10)throw new AssertionError("guard protocol");boolean after=guards.incrementAndGet()==2;if(after){validating.countDown();try{if(!release.await(2,TimeUnit.SECONDS))throw new AssertionError("validation release timeout");}catch(InterruptedException e){throw new AssertionError(e);}}Bundle b=new Bundle();b.putBoolean("ok",!(after?rejectAfter:rejectBefore));b.putString("error","guard rejected");b.putString("home","launcher");b.putInt("width",1248);b.putInt("height",1972);b.putInt("rotation",0);r.bundle=b;return true;};}}
